/* Test-only 1920-pixel XRender GLAMOR texture sampling on private Xwayland.
 * Compare a pixmap generated by XPutImage against its fully composited
 * destination; do not capture any user/third-party windows. */
#define _DEFAULT_SOURCE
#include <X11/Xlib.h>
#include <X11/Xutil.h>
#include <X11/extensions/Xrender.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#define W 1920
#define H 64
static int errs;
static int on_error(Display*d,XErrorEvent *e){char desc[96];XGetErrorText(d,e->error_code,desc,sizeof(desc));fprintf(stderr,"S16_XRENDER_XERROR=%s\n",desc);errs++;return 0;}
int main(void){
 Display*d=XOpenDisplay(NULL);if(!d){puts("S16_XRENDER_DISPLAY=FAIL");return 2;}
 XSetErrorHandler(on_error);
 int screen=DefaultScreen(d);Window root=RootWindow(d,screen);
 Visual*v=DefaultVisual(d,screen);int depth=DefaultDepth(d,screen);
 if(depth!=24&&depth!=32){printf("S16_XRENDER_DEPTH=%d UNSUPPORTED\n",depth);return 3;}
 XRenderPictFormat*format=XRenderFindVisualFormat(d,v);
 if(!format){puts("S16_XRENDER_NO_VISUAL_FORMAT");return 3;}
 Pixmap src=XCreatePixmap(d,root,W,H,depth),dst=XCreatePixmap(d,root,W,H,depth);
 GC gc=XCreateGC(d,src,0,NULL);
 XImage*img=XCreateImage(d,v,depth,ZPixmap,0,NULL,W,H,32,0);
 if(!img || img->bytes_per_line<=0)return 4;
 img->data=calloc((size_t)img->bytes_per_line,H);
 if(!img->data)return 4;
 for(int y=0;y<H;y++)for(int x=0;x<W;x++){
   unsigned long rgb=(x&1)?0x00ff0000u:0x0000ff00u;
   if(y&1)rgb^=0x000000ffu;
   XPutPixel(img,x,y,rgb);
 }
 XPutImage(d,src,gc,img,0,0,0,0,W,H);
 XSetForeground(d,gc,0);XFillRectangle(d,dst,gc,0,0,W,H);
 Picture ps=XRenderCreatePicture(d,src,format,0,NULL),pd=XRenderCreatePicture(d,dst,format,0,NULL);
 if(!ps||!pd){puts("S16_XRENDER_PICTURES=FAIL");return 4;}
 /* Use a true XRender Over texture composite rather than XCopyArea. */
 XRenderComposite(d,PictOpOver,ps,None,pd,0,0,0,0,0,0,W,H);
 XSync(d,False);
 XImage*back=XGetImage(d,dst,0,0,W,H,AllPlanes,ZPixmap);
 if(!back){puts("S16_XRENDER_READ=FAIL");return 5;}
 unsigned long long bad_left=0,bad_right=0;int firstbad=-1,lastbad=-1;
 for(int y=0;y<H;y++)for(int x=0;x<W;x++){
    unsigned long expected=XGetPixel(img,x,y)&0x00ffffffu;
    unsigned long actual=XGetPixel(back,x,y)&0x00ffffffu;
    if(expected!=actual){if(x<W/2)bad_left++;else bad_right++;
      if(firstbad<0)firstbad=x;lastbad=x;}
 }
 printf("S16_XRENDER_GLAMOR_1920_LEFT_BAD=%llu RIGHT_BAD=%llu FIRST_BAD_X=%d LAST_BAD_X=%d XERRORS=%d\n",bad_left,bad_right,firstbad,lastbad,errs);
 XDestroyImage(back);XDestroyImage(img);
 XRenderFreePicture(d,ps);XRenderFreePicture(d,pd);
 XFreePixmap(d,src);XFreePixmap(d,dst);XFreeGC(d,gc);
 XSync(d,False);XCloseDisplay(d);
 return errs?6:(bad_left||bad_right?7:0);
}
